import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"离下乾上 同人：","description":"京氏易传 - 离下乾上 同人：","frontmatter":{"title":"离下乾上 同人：","description":"京氏易传 - 离下乾上 同人："},"headers":[],"relativePath":"zh/classics/jingshi/057.md","filePath":"zh/classics/jingshi/057.md"}'),r={name:"zh/classics/jingshi/057.md"};function l(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"离下乾上-同人",tabindex:"-1"},[i("离下乾上 同人： "),e("a",{class:"header-anchor",href:"#离下乾上-同人","aria-label":"Permalink to “离下乾上 同人：”"},"​")],-1),e("p",null,"二气同进，健而炎上，【乾务上，离务下。】同途异致，性则合也。《易》曰：“出门同人，又谁咎也”。（虎易注：初九象辞。）九二得位居中，六三积阴待应。（虎易注:此两句疑为有误。）《易》曰：“先号咷而后笑”。（虎易注：九五爻辞。）【隔于阳位，不能决胜，先故曰号咷；后获合方喜也，故曰后笑也。】八卦复位，六爻迁次，周而复始。上下不停，生生之义，易道祖也。天与火，明而健；阳道正，阴气和也。【六二居内卦中，能奉于阳。】吉凶故象，五行昭然。【金木水火土，配六位相生。】与坎为飞伏。【己亥水，戊午火。】归魂立三公为世，上九宗庙为应候。",-1),e("p",null,"建始丁巳至壬戌，【小满，寒露。】积算起壬戌至辛酉，周而复始。火土入乾离。【火土二象入乾离，配六宫起积算。】",-1),e("p",null,"五星从位起镇星，【土星入卦，定其吉凶。】觜宿从位降己亥水，【二十八宿，分觜宿入离归魂，配天火同人九三己亥水上。】分气候二十八。【起积算二十八位数，巡六爻有吉凶入何位。】",-1),e("p",null,"火上见金，二气虽同，五行相悖。六爻定位，吉凶之兆在乎五二，得时则顺，失时则逆。阴阳升降，岁月分焉，爻象相荡，内外适变，八卦巡迴，归魂复本。本静则象生，故适离为兑入少女，分八卦于兑象。【坎入兑宫八卦。】（虎易注：坎字应为降，迁字之误。）",-1)])])}const f=s(r,[["render",l]]);export{_ as __pageData,f as default};
